// === Tab: mySketch ===
let yoff = 0.0;
let count = 0;

function setup() {
  createCanvas(600, 600);
  colorMode(HSB, 360, 100, 100, 10);
  pixelDensity(1);
  smooth();
  background(25, 70, 90);
	noFill();
}

function draw() {  
  if(count == 125){
    // noLoop() removed for animation
  }

  background(25, 70, 90, 0.1);
  strokeWeight(1.5);

  let d = width/70
  let xoff = 0.0;

	for (x = 0; x < width+d; x+=(Math.max(0.001, Math.abs(d)) || 1)) {
    let ny = map(noise(xoff, yoff), 0, 1, -200, 550);
    noiseWave(x, ny);
    xoff += 10;
  }

  for (x = 0; x < width+d; x+=(Math.max(0.001, Math.abs(d)) || 1)) {
    var ny = map(noise(xoff, yoff), 0, 1, 0, 650);
    noiseWave_1(x, ny);
    xoff += 10;
  }

  for (x = 0; x < width+d; x+=(Math.max(0.001, Math.abs(d)) || 1)) {
    var ny = map(noise(xoff, yoff), 0, 1, 10, 800);
    noiseWave_2(x, ny);
    xoff += 10;
  } 
  yoff += 0.1;   
  count ++;
}

function noiseWave(x, y) {
  for (let i = 0; i < 15; i++) {
    push();
    translate(x, y);
    stroke(225, 100, 90);
    ellipse(0, 0, i*10); //*5
    pop();
  }  
}

function noiseWave_1(x, y) {
  for (let i = 0; i < 15; i++) {
    push();
    translate(x, y);
    stroke(random(200,320), 100, 100);
    ellipse(0, 0, i*10); //*5
    pop();
  }
}

function noiseWave_2(x, y) {
  for (let i = 0; i < 15; i++) {
    push();
    translate(x, y);
    stroke(256);
    ellipse(0, 0, i*10); //*5
		pop();
  }
}
